#include <stdio.h>
#include <stdlib.h>

#define MAXN 1000005

long long L[MAXN];

// Fast I/O for reading integers
static inline long long read_long() {
    long long x = 0;
    int c = getchar_unlocked();
    while (c < '0' || c > '9') {
        c = getchar_unlocked();
    }
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return x;
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    for (int i = 0; i < N; i++) {
        L[i] = read_long();
    }

    int i = 0;
    int j = N - 1;
    long long sum_left = L[0];
    long long sum_right = L[N - 1];
    int ops = 0;

    while (i < j) {
        if (sum_left == sum_right) {
            i++;
            j--;
            sum_left = L[i];
            sum_right = L[j];
        } else if (sum_left < sum_right) {
            i++;
            sum_left += L[i];
            ops++;
        } else {
            j--;
            sum_right += L[j];
            ops++;
        }
    }

    printf("%d\n", ops);

    return 0;
}
